it("Andalucía 2025: captura íntegra SES/PDF, doce casillas exactas y dos ausencias", () => {
  expect(ses.byteLength).toBe(2034)
  expect(pdf.byteLength).toBe(142159)
  expect(createHash("sha256").update(ses).digest("hex")).toBe(
    "84891c615682be96042b5bcc3d53f0407ad0219e87add316946941cfa7d8e357"
  )
  expect(createHash("sha256").update(pdf).digest("hex")).toBe(
    "9e30e0c4f600fb98a7f64e23120fa3929c0efaf03b7fd9dc4b898fd910c722df"
  )
  expect(pdf.subarray(0, 4).toString()).toBe("%PDF")
  const text = inflateSync(ses).toString("latin1")
  expect(text).toContain('EjModelo="2025"')
  expect(text).toContain("CAD_D~1~ANDALUCIA")
  expect(text).toContain("IDII~1~25000.17")
  const r = Effect.runSync(
    liquidarIrpfAnualExplicito(
      Schema.decodeUnknownSync(CasoFiscalAnualExplicito)(entrada)
    )
  )
  const actual = [
    r.reduccionArt20,
    r.rendimientoNetoReducido,
    r.baseImponibleGeneral,
    r.baseLiquidableGeneral,
    r.componentesCuota.gravamenEstatal,
    r.componentesCuota.gravamenAutonomico,
    r.componentesCuota.gravamenMinimoEstatal,
    r.componentesCuota.gravamenMinimoAutonomico,
    r.componentesCuota.cuotaEstatal,
    r.componentesCuota.cuotaAutonomica,
    r.deduccionTrabajo,
    r.cuotaPosterior,
    r.cuotaDiferencial,
    r.cuotaDiferencialPresentada,
  ]
  const keys = [
    "TPRRT",
    "TPTOTAL",
    "BLGRAL",
    "BLGGRAV",
    "CEXGE1",
    "CEXGA1",
    "CEXGE2",
    "CEXGA2",
    "CIGEST",
    "CIGAUT",
    "CLDED2",
    "CAUTLIQ",
    "CDIF",
    "RESULTADO",
  ]
  const boxes = [
    "0023",
    "0025",
    "0500",
    "0505",
    "0528",
    "0529",
    "0530",
    "0531",
    "0532",
    "0533",
    "0414",
    "0595",
    "0610",
    "0670",
  ]
  let presentes = 0
  const ausentes: string[] = []
  keys.forEach((key, i) => {
    const records = [
      ...text.matchAll(new RegExp(`^   ${key}~1~([^\\r\\n]+)$`, "gm")),
    ]
    if (records.length === 0) {
      ausentes.push(boxes[i]!)
      return
    }
    expect(records).toHaveLength(1)
    const expected = records[0]![1]!
    expect.soft(new Decimal(actual[i]!).eq(expected), boxes[i]).toBe(true)
    presentes++
  })
  expect(presentes).toBe(12)
  expect(ausentes).toEqual(["0023", "0414"])
})

it("Andalucía: esta captura no habilita redondeo art20 ni DA61", () => {
  const caso = Schema.decodeUnknownSync(CasoFiscalAnualExplicito)({
    ...entrada,
    trabajo: {
      ...entrada.trabajo,
      rendimientos: [
        {
          ...entrada.trabajo.rendimientos[0],
          integro: "16576.01",
          cotizaciones: {
            clase: "efectivas",
            seguridadSocial: "0",
            derechosPasivos: "0",
            colegiosHuerfanos: "0",
          },
          sindicato: { importe: "0", satisfecho: "no" },
          colegio: {
            importe: "0",
            satisfecho: "no",
            obligatorio: "no",
            finesEsenciales: "no",
          },
          defensa: {
            importe: "0",
            satisfecho: "no",
            litigioDirectoPagador: "no",
          },
        },
      ],
    },
  })
  const r = Effect.runSync(liquidarIrpfAnualExplicito(caso))
  // Regresión sintética: 7302 − 1.75 × (16576.01 − 14852) = 4284.9825.
  // No es otra observación oficial.
  expect(r.reduccionArt20).toBe("4284.9825")
  expect(r.deduccionTrabajo).toBe("339.998")
})

it("pensión andaluza conserva cuotas decimales; no es la captura de empleo", () => {
  const caso = Schema.decodeUnknownSync(CasoFiscalAnualExplicito)({
    ...entrada,
    trabajo: {
      ...entrada.trabajo,
      rendimientos: entrada.trabajo.rendimientos.map((r) => ({
        ...r,
        clase: "pension",
      })),
    },
  })
  const r = Effect.runSync(liquidarIrpfAnualExplicito(caso))
  expect(r.componentesCuota.gravamenEstatal).toBe("2149.758")
  expect(r.componentesCuota.gravamenAutonomico).toBe("2128.6064")
  expect(r.cuotaDiferencial).toBe("101.0344")
})

it.each(["murcia"])(
  "%s: no extrapola cuotas desde Andalucía",
  (comunidadAutonoma) => {
    const caso = Schema.decodeUnknownSync(CasoFiscalAnualExplicito)({
      ...entrada,
      comunidadAutonoma,
    })
    const r = Effect.runSync(liquidarIrpfAnualExplicito(caso))
    expect(r.componentesCuota.gravamenEstatal).toBe("2149.758")
  }
)

it("Andalucía con derechos familiares conserva la política decimal previa", () => {
  const caso = Schema.decodeUnknownSync(CasoFiscalAnualExplicito)({
    ...entrada,
    familiaresConDerechoMinimo: "segun-derechos",
    derechosMinimos: {
      ...derechos,
      territorio: "andalucia",
      descendientes: derechos.descendientes.map((d) => ({
        ...d,
        titulares: d.titulares.map((t) => ({
          ...t,
          rentasNoExentasCentimos: 2044672,
        })),
      })),
    },
  })
  const r = Effect.runSync(liquidarIrpfAnualExplicito(caso))
  expect(r.componentesCuota.gravamenEstatal).toBe("2149.758")
})
